<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { api } from '../../services/api.js';
import { workspace } from '../../services/workspace.js';
import { auth } from '../../services/auth.js';
import { notify } from '../../services/notifications.js';
import { money, date } from '../../services/panel.js';
import Icon from '../../components/Icon.vue';

const route=useRoute(),router=useRouter();
const loading=ref(true),working=ref(false),error=ref(''),data=ref(null),activeNetwork=ref('facebook');
const products=reactive({facebook:[],instagram:[]});
const sandbox=reactive({facebook:{accessToken:'',adAccountId:'',pageId:''},instagram:{accessToken:'',adAccountId:'',pageId:'',instagramUserId:''}});
const assets=reactive({facebook:{adAccountId:'',pageId:''},instagram:{adAccountId:'',pageId:'',instagramUserId:''}});
const ads=reactive({facebook:{productId:'',name:'',primaryText:'',headline:'',dailyBudget:1000,countryCode:'AR'},instagram:{productId:'',name:'',primaryText:'',headline:'',dailyBudget:1000,countryCode:'AR'}});
const facebook=computed(()=>data.value?.facebook||{});
const instagram=computed(()=>data.value?.instagram||{});
const current=computed(()=>data.value?.[activeNetwork.value]||{});
const integration=computed(()=>current.value.integration||null);
const connected=computed(()=>Boolean(integration.value));
const isAdmin=computed(()=>auth.user?.role==='admin');
const connectionReady=computed(()=>integration.value?.status==='connected');
const selectedAccount=computed(()=>integration.value?.adAccounts?.find(item=>item.id===integration.value?.selectedAdAccountId));
const currentProducts=computed(()=>products[activeNetwork.value]||[]);
const eligibleProducts=computed(()=>currentProducts.value.filter(item=>/^https?:\/\//i.test(item.imageUrl||'')));
const currentAssets=computed(()=>assets[activeNetwork.value]);
const currentAd=computed(()=>ads[activeNetwork.value]);
const providerLabel=computed(()=>activeNetwork.value==='instagram'?'Instagram':'Facebook');
const canCreate=computed(()=>connectionReady.value&&integration.value?.selectedAdAccountId&&integration.value?.selectedPageId&&(activeNetwork.value!=='instagram'||integration.value?.selectedInstagramUserId)&&eligibleProducts.value.length>0);
const networkDescription={facebook:'Conectá una Página y una cuenta publicitaria para crear anuncios desde MiTiendaYa.',instagram:'Conectá una cuenta profesional de Instagram y creá anuncios desde MiTiendaYa.',youtube:'La integración de campañas de YouTube llegará en una próxima versión.',tiktok:'La integración publicitaria con TikTok llegará en una próxima versión.',google:'La integración con Google Ads llegará en una próxima versión.'};
const budget=value=>new Intl.NumberFormat('es-AR',{minimumFractionDigits:0,maximumFractionDigits:2}).format(Number(value||0));

function providerStatus(key){const item=data.value?.[key];if(!item?.integration)return 'Disponible';return item.integration.status==='connected'?'Conectado':'Revisar conexión';}
function syncAssets(provider){const item=data.value?.[provider]?.integration;assets[provider].adAccountId=item?.selectedAdAccountId||'';assets[provider].pageId=item?.selectedPageId||'';if(provider==='instagram')assets.instagram.instagramUserId=item?.selectedInstagramUserId||'';}
function syncInstagramIdentity(){const page=instagram.value?.integration?.pages?.find(item=>item.id===assets.instagram.pageId);assets.instagram.instagramUserId=page?.instagramUserId||'';}
async function loadProducts(provider){if(!data.value?.[provider]?.integration){products[provider]=[];return;}products[provider]=await api.get(`/stores/${workspace.activeStoreId}/social/${provider}/products`);}
async function load(){loading.value=true;error.value='';try{data.value=await api.get(`/stores/${workspace.activeStoreId}/social`);syncAssets('facebook');syncAssets('instagram');await Promise.all(['facebook','instagram'].map(loadProducts));}catch(e){error.value=e.message}finally{loading.value=false}}
onMounted(async()=>{if(route.query.network==='instagram')activeNetwork.value='instagram';for(const provider of ['facebook','instagram']){if(route.query[provider]==='connected')notify.success(`${provider==='instagram'?'Instagram':'Facebook'} quedó conectado a esta tienda.`);if(route.query[provider]==='error')notify.error(String(route.query.message||`No se pudo conectar ${provider==='instagram'?'Instagram':'Facebook'}.`));}if(route.query.facebook||route.query.instagram||route.query.network)await router.replace({path:route.path,query:{}});await load();});
async function connect(provider=activeNetwork.value){working.value=true;try{const result=await api.post(`/stores/${workspace.activeStoreId}/social/${provider}/connect`,{});window.location.assign(result.authUrl)}catch(e){notify.error(e.message);working.value=false}}
async function connectSandbox(provider=activeNetwork.value){working.value=true;try{await api.post(`/stores/${workspace.activeStoreId}/social/${provider}/sandbox`,sandbox[provider]);sandbox[provider].accessToken='';notify.success(`Sandbox de ${provider==='instagram'?'Instagram':'Facebook'} conectado.`);await load()}catch(e){notify.error(e.message)}finally{working.value=false}}
async function saveAssets(provider=activeNetwork.value){working.value=true;try{if(provider==='instagram')syncInstagramIdentity();await api.put(`/stores/${workspace.activeStoreId}/social/${provider}/assets`,assets[provider]);notify.success(`Activos de ${provider==='instagram'?'Instagram':'Facebook'} actualizados.`);await load()}catch(e){notify.error(e.message)}finally{working.value=false}}
async function refreshAssets(provider=activeNetwork.value){working.value=true;try{await api.post(`/stores/${workspace.activeStoreId}/social/${provider}/refresh`,{});notify.success(`Activos de ${provider==='instagram'?'Instagram':'Facebook'} actualizados.`);await load()}catch(e){notify.error(e.message)}finally{working.value=false}}
async function disconnect(provider=activeNetwork.value){working.value=true;try{await api.delete(`/stores/${workspace.activeStoreId}/social/${provider}`);products[provider]=[];notify.success(`${provider==='instagram'?'Instagram':'Facebook'} fue desconectado de esta tienda.`);await load()}catch(e){notify.error(e.message)}finally{working.value=false}}
function productChanged(provider=activeNetwork.value){const form=ads[provider];const product=products[provider].find(item=>item._id===form.productId);if(!product)return;if(!form.name)form.name=`${product.name} · MiTiendaYa`;if(!form.headline)form.headline=product.name;if(!form.primaryText)form.primaryText=product.description||`Conocé ${product.name} en nuestra tienda.`;}
async function createAd(provider=activeNetwork.value){working.value=true;try{const form=ads[provider];const created=await api.post(`/stores/${workspace.activeStoreId}/social/${provider}/ads`,form);notify.success(`Anuncio creado en ${provider==='instagram'?'Instagram':'Facebook'} en estado pausado (${created.external?.adId||'OK'}).`);form.name='';form.primaryText='';form.headline='';await load()}catch(e){notify.error(e.message)}finally{working.value=false}}
</script>

<template>
<div>
  <header class="p-page-header"><div><p class="p-eyebrow">DIFUSIÓN DE TU TIENDA</p><h1>Redes sociales y anuncios</h1><p>Conectá los canales de esta tienda y administrá sus integraciones publicitarias desde un solo lugar.</p></div></header>
  <div v-if="error" class="p-error">{{error}} <button class="btn btn-text" type="button" @click="load">Reintentar</button></div>
  <div v-if="loading" class="p-loading-page"><span class="p-spinner"/>Preparando integraciones...</div>
  <template v-else-if="data">
    <section class="network-grid" aria-label="Redes sociales disponibles">
      <button v-for="network in data.networks" :key="network.key" type="button" class="network-card" :class="{'network-card-active':activeNetwork===network.key,'network-card-soon':network.status!=='available'}" :disabled="network.status!=='available'" @click="network.status==='available'&&(activeNetwork=network.key)">
        <div class="network-mark">{{network.label.slice(0,1)}}</div><div><strong>{{network.label}}</strong><p>{{networkDescription[network.key]}}</p></div><span class="badge" :class="network.status==='available'?'badge-success':''">{{network.status==='available'?providerStatus(network.key):'Muy pronto'}}</span>
      </button>
    </section>

    <template v-if="activeNetwork==='facebook'">
      <section class="p-section-card facebook-card">
        <div class="p-section-title"><div><h2>Facebook Ads</h2><p>{{isAdmin?`Marketing API ${facebook.apiVersion} · Los anuncios creados desde esta pantalla nacen siempre pausados.`:'Creá anuncios para tus productos y revisalos antes de activarlos en Facebook.'}}</p></div><span class="badge" :class="connectionReady?'badge-success':'badge-warning'">{{connected?(connectionReady?'Conectado':'Revisar conexión'):'Sin conectar'}}</span></div>
        <div v-if="!connected" class="facebook-connect-grid" :class="{'facebook-connect-grid-seller':!isAdmin}">
          <div class="connect-option"><h3>Conexión normal</h3><p>Iniciá sesión en Meta, autorizá MiTiendaYa y después elegí la cuenta publicitaria y la Página que va a representar a tu tienda.</p><button class="btn btn-primary" type="button" :disabled="working||!facebook.oauthConfigured" @click="connect('facebook')"><Icon name="link" :size="15"/>{{working?'Conectando…':'Conectar con Facebook'}}</button><small v-if="!facebook.oauthConfigured">{{isAdmin?'Falta completar la configuración general de Facebook.':'La conexión con Facebook todavía no está disponible. Contactá a la administración.'}}</small></div>
          <details v-if="isAdmin&&facebook.sandboxAllowed" class="connect-option sandbox-option"><summary>Prueba sin gasto · Marketing API Sandbox</summary><p>Herramienta de prueba para administración. Permite validar la integración sin publicar anuncios reales.</p><div class="p-form-grid"><div class="p-field full"><label for="sandbox-token">Sandbox Access Token</label><input id="sandbox-token" v-model.trim="sandbox.facebook.accessToken" type="password" autocomplete="off" placeholder="EAA..."/></div><div class="p-field"><label for="sandbox-account">Ad Account ID</label><input id="sandbox-account" v-model.trim="sandbox.facebook.adAccountId" placeholder="act_123456789"/></div><div class="p-field"><label for="sandbox-page">Facebook Page ID</label><input id="sandbox-page" v-model.trim="sandbox.facebook.pageId" placeholder="123456789"/></div></div><button class="btn btn-secondary" type="button" :disabled="working||!sandbox.facebook.accessToken||!sandbox.facebook.adAccountId||!sandbox.facebook.pageId" @click="connectSandbox('facebook')">Conectar Sandbox</button></details>
        </div>
        <template v-else>
          <div class="connection-summary"><div><span>Conexión</span><strong>{{isAdmin?(integration.connectionMode==='sandbox'?'Sandbox (sin entrega)':'OAuth de Facebook'):'Facebook'}}</strong></div><div><span>Cuenta</span><strong>{{integration.externalUserName||'Facebook'}}</strong></div><div><span>Última validación</span><strong>{{integration.lastValidatedAt?date(integration.lastValidatedAt):'—'}}</strong></div></div>
          <div v-if="integration.lastError" class="p-error">{{integration.lastError}}</div>
          <div class="p-form-grid asset-form"><div class="p-field"><label for="facebook-ad-account">Cuenta publicitaria</label><select id="facebook-ad-account" v-model="assets.facebook.adAccountId"><option value="">Elegí una cuenta</option><option v-for="account in integration.adAccounts" :key="account.id" :value="account.id">{{account.name}} · {{account.id}} · {{account.currency}}</option></select></div><div class="p-field"><label for="facebook-page">Página de Facebook</label><select id="facebook-page" v-model="assets.facebook.pageId"><option value="">Elegí una Página</option><option v-for="page in integration.pages" :key="page.id" :value="page.id">{{page.name}}</option></select></div></div>
          <div class="p-inline connection-actions"><button class="btn btn-primary" type="button" :disabled="working||!assets.facebook.adAccountId||!assets.facebook.pageId" @click="saveAssets('facebook')">Guardar selección</button><button class="btn btn-secondary" type="button" :disabled="working" @click="refreshAssets('facebook')"><Icon name="refresh" :size="15"/>Actualizar activos</button><button class="btn btn-text" type="button" :disabled="working" @click="disconnect('facebook')">Desconectar</button></div>
        </template>
      </section>
    </template>

    <template v-else-if="activeNetwork==='instagram'">
      <section class="p-section-card instagram-card">
        <div class="p-section-title"><div><h2>Instagram Ads</h2><p>{{isAdmin?`Marketing API ${instagram.apiVersion} · Se usa instagram_user_id y los anuncios nacen pausados.`:'Conectá tu cuenta profesional de Instagram y creá anuncios de tus productos.'}}</p></div><span class="badge" :class="connectionReady?'badge-success':'badge-warning'">{{connected?(connectionReady?'Conectado':'Revisar conexión'):'Sin conectar'}}</span></div>
        <div v-if="!connected" class="facebook-connect-grid" :class="{'facebook-connect-grid-seller':!isAdmin}">
          <div class="connect-option"><h3>Conectar Instagram</h3><p>Iniciá sesión con Meta y elegí una cuenta profesional de Instagram vinculada a una Página que administres.</p><button class="btn btn-primary" type="button" :disabled="working||!instagram.oauthConfigured" @click="connect('instagram')"><Icon name="link" :size="15"/>{{working?'Conectando…':'Conectar con Instagram'}}</button><small v-if="!instagram.oauthConfigured">{{isAdmin?'Falta completar la configuración general de Meta.':'La conexión con Instagram todavía no está disponible. Contactá a la administración.'}}</small></div>
          <details v-if="isAdmin&&instagram.sandboxAllowed" class="connect-option sandbox-option"><summary>Prueba sin gasto · Marketing API Sandbox</summary><p>Permite validar la identidad de Instagram y la creación de anuncios sin entrega real.</p><div class="p-form-grid"><div class="p-field full"><label for="ig-sandbox-token">Sandbox Access Token</label><input id="ig-sandbox-token" v-model.trim="sandbox.instagram.accessToken" type="password" autocomplete="off" placeholder="EAA..."/></div><div class="p-field"><label for="ig-sandbox-account">Ad Account ID</label><input id="ig-sandbox-account" v-model.trim="sandbox.instagram.adAccountId" placeholder="act_123456789"/></div><div class="p-field"><label for="ig-sandbox-page">Facebook Page ID</label><input id="ig-sandbox-page" v-model.trim="sandbox.instagram.pageId" placeholder="123456789"/></div><div class="p-field"><label for="ig-sandbox-user">Instagram User ID</label><input id="ig-sandbox-user" v-model.trim="sandbox.instagram.instagramUserId" placeholder="17841400000000000"/></div></div><button class="btn btn-secondary" type="button" :disabled="working||!sandbox.instagram.accessToken||!sandbox.instagram.adAccountId||!sandbox.instagram.pageId||!sandbox.instagram.instagramUserId" @click="connectSandbox('instagram')">Conectar Sandbox</button></details>
        </div>
        <template v-else>
          <div class="connection-summary"><div><span>Conexión</span><strong>{{isAdmin?(integration.connectionMode==='sandbox'?'Sandbox (sin entrega)':'OAuth de Meta'):'Instagram'}}</strong></div><div><span>Cuenta</span><strong>{{integration.externalUserName||'Instagram'}}</strong></div><div><span>Última validación</span><strong>{{integration.lastValidatedAt?date(integration.lastValidatedAt):'—'}}</strong></div></div>
          <div v-if="integration.lastError" class="p-error">{{integration.lastError}}</div>
          <div class="p-form-grid asset-form"><div class="p-field"><label for="instagram-ad-account">Cuenta publicitaria</label><select id="instagram-ad-account" v-model="assets.instagram.adAccountId"><option value="">Elegí una cuenta</option><option v-for="account in integration.adAccounts" :key="account.id" :value="account.id">{{account.name}} · {{account.id}} · {{account.currency}}</option></select></div><div class="p-field"><label for="instagram-account">Cuenta profesional de Instagram</label><select id="instagram-account" v-model="assets.instagram.pageId" @change="syncInstagramIdentity"><option value="">Elegí una cuenta</option><option v-for="page in integration.pages" :key="page.id+page.instagramUserId" :value="page.id">{{page.instagramUsername?'@'+page.instagramUsername:'Instagram '+page.instagramUserId}} · {{page.name}}</option></select><small>La cuenta debe ser Business o Creator y estar vinculada a la Página indicada.</small></div></div>
          <div class="p-inline connection-actions"><button class="btn btn-primary" type="button" :disabled="working||!assets.instagram.adAccountId||!assets.instagram.pageId||!assets.instagram.instagramUserId" @click="saveAssets('instagram')">Guardar selección</button><button class="btn btn-secondary" type="button" :disabled="working" @click="refreshAssets('instagram')"><Icon name="refresh" :size="15"/>Actualizar activos</button><button class="btn btn-text" type="button" :disabled="working" @click="disconnect('instagram')">Desconectar</button></div>
        </template>
      </section>
    </template>

    <section v-if="connected" class="p-section-card">
      <div class="p-section-title"><div><h2>Crear anuncio de producto</h2><p>El anuncio se crea pausado para que puedas revisarlo antes de activarlo desde {{providerLabel}}.</p></div><Icon name="megaphone"/></div>
      <div v-if="!canCreate" class="p-info"><strong>Antes de crear:</strong> completá los activos de {{providerLabel}} y asegurate de tener al menos un producto activo con una imagen pública válida.</div>
      <form class="p-form" @submit.prevent="createAd(activeNetwork)"><div class="p-form-grid"><div class="p-field full"><label :for="activeNetwork+'-product'">Producto</label><select :id="activeNetwork+'-product'" v-model="currentAd.productId" required @change="productChanged(activeNetwork)"><option value="">Elegí el producto a promocionar</option><option v-for="product in eligibleProducts" :key="product._id" :value="product._id">{{product.name}} · {{money(product.price)}}</option></select><small>El anuncio enlaza directamente a la ficha pública del producto y usa su primera imagen.</small></div><div class="p-field full"><label :for="activeNetwork+'-ad-name'">Nombre interno del anuncio</label><input :id="activeNetwork+'-ad-name'" v-model.trim="currentAd.name" required maxlength="120" placeholder="Remera Naruto · Octubre"/></div><div class="p-field full"><label :for="activeNetwork+'-primary-text'">Texto principal</label><textarea :id="activeNetwork+'-primary-text'" v-model.trim="currentAd.primaryText" required maxlength="1000" rows="4" placeholder="Contale a tu público por qué debería conocer este producto."/></div><div class="p-field full"><label :for="activeNetwork+'-headline'">Título</label><input :id="activeNetwork+'-headline'" v-model.trim="currentAd.headline" required maxlength="255"/></div><div class="p-field"><label :for="activeNetwork+'-budget'">Presupuesto diario</label><input :id="activeNetwork+'-budget'" v-model.number="currentAd.dailyBudget" type="number" min="1" step="0.01" required/><small>{{selectedAccount?.currency||'Moneda de la cuenta'}}. No se consume mientras el anuncio permanezca pausado.</small></div><div class="p-field"><label :for="activeNetwork+'-country'">País objetivo</label><input :id="activeNetwork+'-country'" v-model.trim="currentAd.countryCode" required maxlength="2" pattern="[A-Za-z]{2}"/><small>Código ISO de dos letras. Por defecto AR.</small></div></div><div class="p-form-actions"><button class="btn btn-primary" :disabled="working||!canCreate">{{working?`Creando en ${providerLabel}…`:'Crear anuncio pausado'}}</button></div></form>
    </section>

    <section v-if="connected" class="p-section-card">
      <div class="p-section-title"><div><h2>Anuncios creados desde MiTiendaYa</h2><p>Últimos anuncios registrados para {{providerLabel}} en esta tienda.</p></div><Icon name="chart"/></div>
      <div v-if="!current.ads?.length" class="social-empty">Todavía no creaste anuncios de {{providerLabel}} desde MiTiendaYa.</div>
      <div v-else class="ads-list"><article v-for="row in current.ads" :key="row._id"><div><strong>{{row.name}}</strong><small>{{date(row.createdAt)}} · {{row.external?.adId?'Ad '+row.external.adId:'Sin ID externo'}}</small></div><div><span>{{budget(row.dailyBudget)}} {{row.currency}}</span><span class="badge badge-warning">Pausado</span></div></article></div>
    </section>

    <section v-if="isAdmin" class="p-section-card setup-help">
      <div class="p-section-title"><div><h2>{{activeNetwork==='instagram'?'Qué necesita Instagram':'Qué necesita Facebook'}}</h2><p>Recordatorio técnico visible únicamente para administración.</p></div><Icon name="info"/></div>
      <dl v-if="activeNetwork==='facebook'"><div><dt>META_APP_ID</dt><dd>Identifica tu aplicación de Meta cuando un vendedor inicia la conexión.</dd></div><div><dt>META_APP_SECRET</dt><dd>Permite intercambiar la autorización y firmar llamadas.</dd></div><div><dt>META_REDIRECT_URI</dt><dd>URL autorizada para el retorno de Facebook.</dd></div><div><dt>Permisos</dt><dd><code>{{facebook.requiredScopes?.join(', ')}}</code></dd></div></dl>
      <dl v-else><div><dt>META_APP_ID / SECRET</dt><dd>Instagram Ads usa la misma aplicación de Meta que Facebook Ads.</dd></div><div><dt>META_INSTAGRAM_REDIRECT_URI</dt><dd>URL autorizada para el retorno de la conexión de Instagram.</dd></div><div><dt>Cuenta profesional</dt><dd>Debe ser Business o Creator y estar vinculada a una Página administrada por el usuario.</dd></div><div><dt>Permisos</dt><dd><code>{{instagram.requiredScopes?.join(', ')}}</code></dd></div></dl>
    </section>
  </template>
</div>
</template>

<style scoped>
.network-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px;margin-bottom:22px}.network-card{appearance:none;text-align:left;font:inherit;color:inherit;display:grid;grid-template-columns:44px 1fr;gap:12px;position:relative;padding:18px;border:1px solid var(--line);border-radius:13px;background:var(--surface);opacity:.72;cursor:pointer}.network-card:not(:disabled):hover{border-color:var(--line-strong);transform:translateY(-1px)}.network-card-active{opacity:1;border-color:var(--primary);box-shadow:0 0 0 1px var(--primary)}.network-card-soon{cursor:default}.network-card>.badge{grid-column:2;justify-self:start}.network-mark{width:44px;height:44px;border-radius:12px;display:grid;place-items:center;background:var(--surface-alt);font-size:18px;font-weight:800}.network-card strong{font-size:13px}.network-card p{margin:5px 0 0;color:var(--muted);font-size:11px;line-height:1.5}.facebook-card,.instagram-card{margin-top:0}.facebook-connect-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.facebook-connect-grid-seller{grid-template-columns:1fr}.facebook-connect-grid-seller .connect-option{width:100%}.connect-option{border:1px solid var(--line);border-radius:12px;padding:18px}.connect-option h3{margin:0 0 6px}.connect-option p{font-size:12px;color:var(--muted);line-height:1.6}.connect-option>small{display:block;margin-top:10px;color:var(--muted)}.sandbox-option summary{cursor:pointer;font-weight:700;font-size:13px}.sandbox-option[open] summary{margin-bottom:10px}.connection-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:20px}.connection-summary>div{display:flex;flex-direction:column;gap:5px;border:1px solid var(--line);border-radius:10px;padding:14px}.connection-summary span{font-size:10px;color:var(--muted);text-transform:uppercase;font-weight:750}.connection-summary strong{font-size:12px;overflow-wrap:anywhere}.asset-form{margin-top:10px}.connection-actions{margin-top:16px;flex-wrap:wrap}.social-empty{padding:24px;border:1px dashed var(--line);border-radius:10px;color:var(--muted);font-size:12px}.ads-list{display:grid;gap:10px}.ads-list article{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px;border:1px solid var(--line);border-radius:10px}.ads-list article>div{display:flex;flex-direction:column;gap:4px}.ads-list small{color:var(--muted);font-size:10px}.ads-list article>div:last-child{align-items:flex-end}.setup-help dl{display:grid;gap:0;margin:0}.setup-help dl>div{display:grid;grid-template-columns:220px 1fr;gap:18px;padding:14px 0;border-bottom:1px solid var(--line)}.setup-help dl>div:last-child{border-bottom:0}.setup-help dt{font-size:12px;font-weight:700}.setup-help dd{margin:0;font-size:12px;line-height:1.6;color:var(--muted);overflow-wrap:anywhere}.setup-help code{font-size:10px}@media(max-width:1200px){.network-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:1000px){.network-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.network-grid,.facebook-connect-grid,.connection-summary{grid-template-columns:1fr}.setup-help dl>div{grid-template-columns:1fr;gap:5px}.ads-list article{align-items:flex-start;flex-direction:column}.ads-list article>div:last-child{align-items:flex-start}}
</style>
